from __future__ import annotations

GODOT_PROJECT_SOURCE = '''; Kodepoia R10.10 canonical local acceptance project\nconfig_version=5\n\n[application]\nconfig/name="Kodepoia R10.10 Acceptance"\nrun/main_scene="res://validator.tscn"\n\n[rendering]\nrenderer/rendering_method="gl_compatibility"\nrenderer/rendering_method.mobile="gl_compatibility"\n'''

GODOT_VALIDATOR_SCENE_SOURCE = '''[gd_scene load_steps=2 format=3]\n\n[ext_resource type="Script" path="res://validator.gd" id="1_script"]\n\n[node name="R1010Validator" type="Node"]\nscript = ExtResource("1_script")\n'''

GODOT_VALIDATOR_SCRIPT_SOURCE = '''extends Node\n\nconst STATIC_PATH: String = "res://assets/static.glb"\nconst RIGGED_PATH: String = "res://assets/rigged.glb"\n\nfunc _walk(node: Node, facts: Dictionary) -> void:\n    if node is MeshInstance3D:\n        facts["meshes"] = int(facts["meshes"]) + 1\n        var mesh_instance: MeshInstance3D = node as MeshInstance3D\n        if mesh_instance.mesh != null:\n            facts["surfaces"] = int(facts["surfaces"]) + mesh_instance.mesh.get_surface_count()\n            for surface_index: int in range(mesh_instance.mesh.get_surface_count()):\n                if mesh_instance.mesh.surface_get_material(surface_index) != null:\n                    facts["materials"] = int(facts["materials"]) + 1\n    if node is Skeleton3D:\n        var skeleton: Skeleton3D = node as Skeleton3D\n        facts["skeletons"] = int(facts["skeletons"]) + 1\n        facts["bones"] = int(facts["bones"]) + skeleton.get_bone_count()\n    if node is AnimationPlayer:\n        var player: AnimationPlayer = node as AnimationPlayer\n        facts["animation_players"] = int(facts["animation_players"]) + 1\n        facts["animations"] = int(facts["animations"]) + player.get_animation_list().size()\n    for child: Node in node.get_children():\n        _walk(child, facts)\n\nfunc _inspect(path: String) -> Dictionary:\n    var facts: Dictionary = {\n        "meshes": 0,\n        "surfaces": 0,\n        "materials": 0,\n        "skeletons": 0,\n        "bones": 0,\n        "animation_players": 0,\n        "animations": 0,\n    }\n    var resource: Resource = load(path)\n    if not resource is PackedScene:\n        facts["load_failed"] = true\n        return facts\n    var packed: PackedScene = resource as PackedScene\n    var instance: Node = packed.instantiate()\n    add_child(instance)\n    _walk(instance, facts)\n    remove_child(instance)\n    instance.free()\n    facts["load_failed"] = false\n    return facts\n\nfunc _ready() -> void:\n    var static_facts: Dictionary = _inspect(STATIC_PATH)\n    var rigged_facts: Dictionary = _inspect(RIGGED_PATH)\n    var failures: Array[String] = []\n    if bool(static_facts.get("load_failed", true)) or int(static_facts["meshes"]) < 1 or int(static_facts["materials"]) < 1:\n        failures.append("static_import_semantics")\n    if bool(rigged_facts.get("load_failed", true)) or int(rigged_facts["meshes"]) < 1:\n        failures.append("rigged_mesh_missing")\n    if int(rigged_facts["skeletons"]) < 1 or int(rigged_facts["bones"]) < 2:\n        failures.append("rigged_skeleton_missing")\n    if int(rigged_facts["animation_players"]) < 1 or int(rigged_facts["animations"]) < 1:\n        failures.append("rigged_animation_missing")\n    if failures.is_empty():\n        print("KODEPOIA_R10_10_GODOT_PASS")\n        print(JSON.stringify({"static": static_facts, "rigged": rigged_facts}))\n        get_tree().quit(0)\n    else:\n        printerr("KODEPOIA_R10_10_GODOT_FAIL:" + ",".join(failures))\n        get_tree().quit(19)\n'''
